    'restore_missing_sharekeys' => 'Restaurar sharekeys faltantes',
    'restore_missing_sharekeys_tip' => 'Esta herramienta detecta y recrea sharekeys de cifrado faltantes (elementos, campos personalizados y archivos). Los usuarios sin una sharekey ven el objeto pero no pueden descifrarlo (icono de contraseña tachado). El análisis es una pasada de solo lectura. La reparación primero restaura las claves de referencia de la cuenta interna de TP usando su propia cuenta, y luego una tarea en segundo plano distribuye las claves faltantes a cada usuario. Solo se crean las claves faltantes - las claves existentes nunca se modifican. Los elementos personales se manejan por separado: su clave se reconstruye únicamente para su propietario, nunca se distribuye.',
