    'microlearning_title' => 'Consejo de seguridad',
    'microlearning_got_it' => 'Entendido — no volver a mostrar',
    'microlearning_mute_all' => 'Silenciar todos los consejos',
    'microlearning_tip_unique_password' => 'Utilice una contraseña diferente para cada cuenta: si un sitio se filtra, los demás permanecen seguros. El generador crea una para usted en un clic.',
    'microlearning_tip_passphrase' => 'Lo largo supera a lo complejo: una frase de contraseña compuesta por varias palabras aleatorias es más fácil de recordar y mucho más difícil de descifrar que "P@ssw0rd1".',
    'microlearning_tip_secure_share' => 'Nunca envíe una contraseña por correo o chat; esas copias se quedan para siempre. Un enlace de un solo uso expira y solo se puede abrir el número de veces que permita.',
    'microlearning_tip_what_is_mfa' => 'La autenticación de doble factor (MFA) añade un segundo cerrojo: aunque alguien robe su contraseña, no podrá iniciar sesión sin su teléfono. Habilítela en su perfil.',
    'microlearning_tip_reuse_risk' => 'Reutilizar una contraseña es como tener una sola llave para su casa, coche y oficina: si la pierde una vez, lo pierde todo. El panel de seguridad muestra cuáles de sus contraseñas están reutilizadas.',
    'microlearning_tip_phishing' => 'TeamPass nunca le pedirá su contraseña por correo electrónico. En caso de duda, no haga clic en el enlace; abra TeamPass desde sus marcadores.',
    'microlearning_tip_browser_extension' => 'La extensión del navegador rellena sus contraseñas únicamente en el sitio correcto: una defensa sólida contra páginas de suplantación de identidad (phishing). Configúrela desde su perfil en un clic.',
    'microlearning_tip_breach_check' => 'Una contraseña puede ser robusta Y estar ya expuesta públicamente: las bases de datos de filtraciones contienen miles de millones. Use la comprobación de filtraciones en sus elementos de vez en cuando.',
    'microlearning_tip_expiry' => 'Las credenciales críticas deben rotarse periódicamente. Las carpetas pueden tener un período de renovación; los elementos que lo superan se marcan en su panel de control.',
    'microlearning_tip_lock_leaving' => '¿Se ausenta de su escritorio? Bloquee su sesión (Win+L / Ctrl+Cmd+Q). Un gestor de contraseñas abierto en una pantalla desatendida anula cualquier otra protección.',
    'settings_micro_learning' => 'Microaprendizaje de seguridad en contexto',
    'settings_micro_learning_tip' => 'Muestra consejos breves de seguridad descartables en el momento de realizar una acción (crear un elemento, compartir un secreto...) además de un consejo general al día. Los usuarios pueden descartar cualquier consejo o silenciarlos todos sin bloquear su trabajo.',
