    'licence_server_key_rotated' => 'El servidor de licencias firma sus respuestas con una clave que esta versión de TeamPass no conoce. No se puede verificar nada, por lo que no se utiliza nada. Actualice TeamPass o escriba a contact@teampass.net.',
    'licence_server_unreachable_title' => 'Servidor de licencias inaccesible',
    'licence_server_unreachable_body' => 'Este servidor no ha podido contactar con el servidor de licencias. No se ha enviado nada. Esto suele significar que el servidor de TeamPass no tiene acceso a Internet saliente o que se encuentra tras un proxy.',
    'licence_trial_offline_title' => 'Solicite la prueba desde otro equipo',
    'licence_trial_offline_intro' => 'Abra el siguiente enlace desde un equipo con acceso a Internet. Se abrirá una página alojada en el servidor de licencias que, una vez confirmada allí, realizará la solicitud que este servidor no pudo hacer. Este paso adicional existe porque el servidor de licencias solo acepta esa solicitud como POST, algo que un enlace no puede hacer.',
    'licence_trial_offline_warning' => 'El enlace contiene la clave de licencia de esta instancia. Trátelo como un secreto: identifica su licencia y la página que abre es el único lugar donde debería pegarse.',
    'licence_trial_offline_contact_tip' => 'El mensaje se envía a esta dirección, y el enlace que lleva la designa como el contacto de la prueba: el servidor de licencias enviará su confirmación allí. Debe pertenecer al dominio de esta instancia:',
    'licence_trial_offline_send_button' => 'Enviarme el enlace',
    'licence_trial_offline_send_tip' => 'Utiliza la configuración de correo electrónico de esta instancia, que normalmente sigue funcionando sin acceso a Internet.',
    'licence_trial_offline_copy_button' => 'Copiar el enlace',
    'licence_trial_offline_qr_button' => 'Mostrar un código QR',
    'licence_trial_offline_qr_tip' => 'Escanéelo con un teléfono para abrir la página sin copiar nada.',
    'licence_trial_offline_email_sent' => 'El enlace ha sido enviado.',
    'licence_trial_offline_already_sent' => 'Se envió un enlace de solicitud el',
    'licence_trial_offline_no_feedback' => 'Este servidor no tiene acceso a Internet y nunca podrá confirmar la activación por sí mismo. Eso no impide nada: la extensión del navegador verifica la licencia directamente desde el navegador, por lo que detectará la prueba por sí sola una vez que la haya confirmado por correo electrónico.',
    'licence_trial_offline_email_subject' => 'TEAMPASS - Solicite la prueba de la extensión de su navegador',
    'licence_trial_offline_email_body' => 'Hola,<br><br>Este servidor TeamPass (<strong>#tp_fqdn#</strong>) no puede comunicarse con el servidor de licencias, por lo que no pudo solicitar la prueba de la extensión del navegador por sí mismo.<br><br>Abra el siguiente enlace desde un equipo con acceso a Internet y luego confirme la solicitud en la página:<br><br><a href="#tp_trial_link#">#tp_trial_link#</a><br><br>A continuación se enviará un mensaje de confirmación a <strong>#tp_contact_email#</strong>. Abrir el enlace que contiene activa la prueba de 30 días.<br><br>Dos cosas importantes a tener en cuenta:<br>- se concede una prueba por dominio y producto, de forma permanente;<br>- si solicita un nuevo mensaje de confirmación, el enlace anterior dejará de funcionar.<br><br>Este enlace contiene la clave de licencia de su instancia. No lo reenvíe.',
