    'webauthn_login_tip_passwordless' => 'Una llave de acceso (huella dactilar, rostro, PIN o llave de seguridad) le permite iniciar sesión sin su contraseña, o confirma su inicio de sesión en lugar de un código. Una vez que añada una, TeamPass se la pedirá después de su contraseña en cada inicio de sesión.',
